Meets Minimum:   ${validation.meetsMinimum ? 'YES ✓' : 'NO ✗'}
Within Range:    ${validation.meetsMaximum ? 'YES ✓' : 'NO ✗'}
  `.trim());

  return validation.meetsMinimum && validation.meetsMaximum;
}

